#define ID(x) ({ __auto_type id_x_ = (x); id_x_; })  /* GNU C: eval once, exact type */

int id_int(int x) { return x; }              /* portable ISO C, per type */

/* Comparator identity: neutral element for qsort — every pair 'equal'. */
int ident_cmp(const void *a, const void *b) { (void)a; (void)b; return 0; }

qsort(items, n, sizeof *items, ident_cmp);   /* no derived key / no-op ordering */
